formulas.expression:
if(
  and(
    or(
      text({!Get_Opp.Type}) = "Upsell",
      text({!Get_Opp.Type}) = "Organizational Expansion (Same territory)",
      text({!Get_Opp.Type}) = "Organizational Expansion (Same Parent Account)"
    ),
    isnull({!Get_CS_Owner.Id})
  ),
  "CS Account Owner: <@" & {!Get_CS_Account_Owner.Slack_ID__c} & ">",
null
)

